function permute(nums) {
  const result = [];
  const path = [];
  const used = new Array(nums.length).fill(false);
  const build = () => {
    if (path.length === nums.length) {      // every number placed: one permutation
      result.push([...path]);
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;                 // already in the path
      used[i] = true;                        // choose
      path.push(nums[i]);
      build();                               // explore
      path.pop();                            // un-choose
      used[i] = false;
    }
  };
  build();
  return result;
}

List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    build(nums, new boolean[nums.length], new ArrayList<>(), result);
    return result;
}

void build(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {
    if (path.size() == nums.length) {            // every number placed: one permutation
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;                   // already in the path
        used[i] = true;                          // choose
        path.add(nums[i]);
        build(nums, used, path, result);         // explore
        path.remove(path.size() - 1);            // un-choose
        used[i] = false;
    }
}

void build(vector<int>& nums, vector<bool>& used, vector<int>& path, vector<vector<int>>& result) {
    if (path.size() == nums.size()) {            // every number placed: one permutation
        result.push_back(path);
        return;
    }
    for (int i = 0; i < (int)nums.size(); i++) {
        if (used[i]) continue;                   // already in the path
        used[i] = true;                          // choose
        path.push_back(nums[i]);
        build(nums, used, path, result);         // explore
        path.pop_back();                         // un-choose
        used[i] = false;
    }
}

vector<vector<int>> permute(vector<int>& nums) {
    vector<vector<int>> result;
    vector<int> path;
    vector<bool> used(nums.size(), false);
    build(nums, used, path, result);
    return result;
}

function permute(nums) {
  const a = [...nums];
  const result = [];
  const fill = (i) => {
    if (i === a.length) {
      result.push([...a]);
      return;
    }
    for (let j = i; j < a.length; j++) {
      [a[i], a[j]] = [a[j], a[i]];   // put a[j] at position i
      fill(i + 1);
      [a[i], a[j]] = [a[j], a[i]];   // swap back
    }
  };
  fill(0);
  return result;
}

def permute(nums):
    a, result = nums[:], []

    def fill(i):
        if i == len(a):
            result.append(a[:])
            return
        for j in range(i, len(a)):
            a[i], a[j] = a[j], a[i]       # put a[j] at position i
            fill(i + 1)
            a[i], a[j] = a[j], a[i]       # swap back

    fill(0)
    return result

List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    fill(nums.clone(), 0, result);
    return result;
}

void fill(int[] a, int i, List<List<Integer>> result) {
    if (i == a.length) {
        List<Integer> p = new ArrayList<>();
        for (int x : a) p.add(x);
        result.add(p);
        return;
    }
    for (int j = i; j < a.length; j++) {
        int t = a[i]; a[i] = a[j]; a[j] = t;     // put a[j] at position i
        fill(a, i + 1, result);
        t = a[i]; a[i] = a[j]; a[j] = t;         // swap back
    }
}

void fill(vector<int>& a, int i, vector<vector<int>>& result) {
    if (i == (int)a.size()) {
        result.push_back(a);
        return;
    }
    for (int j = i; j < (int)a.size(); j++) {
        swap(a[i], a[j]);                        // put a[j] at position i
        fill(a, i + 1, result);
        swap(a[i], a[j]);                        // swap back
    }
}

vector<vector<int>> permute(vector<int>& nums) {
    vector<vector<int>> result;
    vector<int> a = nums;
    fill(a, 0, result);
    return result;
}
